/** Bindings and secrets. Secrets are set in the Cloudflare dashboard or by the setup-secrets workflow, never in the repo. */
export interface Env {
  readonly DB: D1Database;
  /** Alpaca paper keys of the dedicated account (secrets). */
  readonly ALPACA_KEY_ID?: string;
  readonly ALPACA_SECRET_KEY?: string;
  /** HMAC key for token and pairing-code hashes (secret, generated by CI). */
  readonly TOKEN_PEPPER?: string;
  /** First-pairing passphrase, chosen by the owner, valid once (secret). */
  readonly PAIR_BOOTSTRAP?: string;
}

/** Outbound fetch, injectable for tests. */
export type FetchFn = (input: URL | string, init?: RequestInit) => Promise<Response>;

export interface Deps {
  readonly fetch: FetchFn;
}

export const defaultDeps: Deps = { fetch: (input, init) => fetch(input, init) };
